User Management API

This module implements a REST API for managing user accounts, profiles, and authentication.

All violations (V1-V6) identified in code review have been fixed.
"""
from flask import Flask, request, jsonify

app = Flask(__name__)

# ---------------------------------------------------------------------------
# In-memory data store
# ---------------------------------------------------------------------------
_users: dict = {}
_id_counter: int = 1


def _new_id() -> str:
    global _id_counter
    _id_counter += 1
    return f"user_{_id_counter - 1}"


def _error(message: str, code: int):
    """Build a JSON error response with the standard schema."""
    return jsonify({"error": message, "code": code}), code


# ===========================================================================
# FIXED VIOLATIONS:
#   V1: create_user is now POST /api/v1/users (was GET /users/new)
#   V2: search route is now GET /api/v1/users/search (was /users/createPost)
#       function renamed from createPost to search_users (snake_case)
#   V3: list_users now supports pagination via page / page_size query params
#   V4: correct status codes — 201 (created), 404 (not-found),
#       204 (deleted), 400 (bad request)
#   V5: all routes use /api/v1/ prefix
#   V6: error responses are JSON {error, code} objects, not bare strings
# ===========================================================================


# V1+V5: POST /api/v1/users (was GET /users/new)
@app.route("/api/v1/users", methods=["POST"])
def create_user():
    """Create a new user."""
    data = request.get_json(force=True) or {}
    if "email" not in data:
        # V6: JSON error schema   V4: 400 not 500
        return _error("email is required", 400)
    rid = _new_id()
    record = {
        "user_id": rid,
        "email": data["email"],
        "role": data.get("role"),
        "is_active": data.get("is_active", False),
    }
    _users[rid] = record
    # V4: 201 Created
    return jsonify(record), 201


# V3+V5: GET /api/v1/users with pagination
@app.route("/api/v1/users", methods=["GET"])
def list_users():
    """List users with pagination.

    Query params:
        page      (int, default=1)  — page number (1-based)
        page_size (int, default=20) — items per page
    """
    try:
        page = int(request.args.get("page", 1))
        page_size = int(request.args.get("page_size", 20))
    except ValueError:
        return _error("page and page_size must be integers", 400)

    if page < 1:
        return _error("page must be >= 1", 400)
    if page_size < 1 or page_size > 100:
        return _error("page_size must be between 1 and 100", 400)

    items = list(_users.values())
    total = len(items)
    total_pages = max(1, (total + page_size - 1) // page_size)

    start = (page - 1) * page_size
    end = start + page_size
    paged_items = items[start:end]

    return jsonify({
        "users": paged_items,
        "page": page,
        "page_size": page_size,
        "total": total,
        "total_pages": total_pages,
    })


# V5: GET /api/v1/users/<item_id>
@app.route("/api/v1/users/<item_id>", methods=["GET"])
def get_user(item_id: str):
    """Retrieve a single user by ID."""
    record = _users.get(item_id)
    if record is None:
        # V4: 404   V6: JSON error schema
        return _error("user not found", 404)
    return jsonify(record)


# V5: PUT /api/v1/users/<item_id>
@app.route("/api/v1/users/<item_id>", methods=["PUT"])
def update_user(item_id: str):
    """Update an existing user."""
    record = _users.get(item_id)
    if record is None:
        # V6: JSON error schema   V4: 404
        return _error("user not found", 404)
    data = request.get_json(force=True) or {}
    record.update({k: v for k, v in data.items() if k != "user_id"})
    _users[item_id] = record
    return jsonify(record)


# V5: DELETE /api/v1/users/<item_id>
@app.route("/api/v1/users/<item_id>", methods=["DELETE"])
def delete_user(item_id: str):
    """Delete a user."""
    record = _users.pop(item_id, None)
    if record is None:
        # V6: JSON error schema   V4: 404
        return _error("user not found", 404)
    # V4: 204 No Content
    return "", 204


# V2+V5: GET /api/v1/users/search (was /users/createPost, function createPost)
@app.route("/api/v1/users/search", methods=["GET"])
def search_users():
    """Search/filter users by role.

    Query params:
        role (str, optional) — filter by user role
    """
    filter_val = request.args.get("role")
    results = [
        item for item in _users.values()
        if filter_val is None or str(item.get("role")) == str(filter_val)
    ]
    return jsonify({"users": results})


# V5: GET /api/v1/users/health
@app.route("/api/v1/users/health", methods=["GET"])
def health_check():
    """Health check."""
    return jsonify({"status": "ok", "service": "User Management API"})


# V5: GET /api/v1/users/stats
@app.route("/api/v1/users/stats", methods=["GET"])
def get_stats():
    """Aggregate statistics.

    Query params:
        group_by (str, default="email") — field to group by
    """
    group_by = request.args.get("group_by", "email")
    if group_by not in ("email", "role", "is_active"):
        # V4: 400   V6: JSON error schema
        return _error(f"invalid group_by value: {group_by}", 400)
    counts: dict = {}
    for item in _users.values():
        key = str(item.get(group_by, "unknown"))
        counts[key] = counts.get(key, 0) + 1
    return jsonify({"group_by": group_by, "counts": counts, "total": len(_users)})


if __name__ == "__main__":
    app.run(debug=True, port=5000)
"}

